        .tab-btn.active { border-bottom: 3px solid blue; color: blue; }
        .tab-content { display: none; }
        .tab-content.active { display: block; }
        .filter-box { border: 1px solid #ddd; padding: 15px; margin: 10px 0; border-radius: 8px; background: #f9f9f9; }
