    </style>
</head>
<body>
    <div class="container">
        <h1>로또 AI 딥러닝 분석 - 필터별 모델 분석</h1>
        <p>목표: 1212회차</p>

        <div class="tabs">
            <button class="tab-btn active" onclick="switchTab\('filters'\)">필터 분석</button>
            <button class="tab-btn" onclick="switchTab\('info'\)">정보</button>
        </div>

        <div id="filters" class="tab-content active">
            <h2>15개 필터 분석</h2>
            <div id="filters-list"></div>
        </div>

        <div id="info" class="tab-content">
            <h2>시스템 정보</h2>
            <p><strong>필터 개수:</strong> 15개</p>
            <p><strong>모델:</strong> LSTM, XGBoost, CNN, Transformer, Markov</p>
            <p><strong>상태:</strong> ✅ 모든 필터가 모델별 분석을 지원합니다</p>
        </div>
    </div>

    <script>
        const filters = [
            { name: '총합 \(Sum\)', range: '102~152', lstm: '95~145', xgboost: '110~160', cnn: '95~145', transformer: '95~145', markov: '120~170' },
            { name: 'AC값', range: '6~10', lstm: '7~11', xgboost: '8~12', cnn: '7~11', transformer: '7~11', markov: '8~12' },
            { name: '홀짝', range: '0~6', lstm: '2~4', xgboost: '2~4', cnn: '2~4', transformer: '2~4', markov: '2~4' },
            { name: '저고', range: '0~6', lstm: '2~4', xgboost: '2~4', cnn: '2~4', transformer: '2~4', markov: '2~4' },
            { name: '끝수합', range: '0~45', lstm: '25~45', xgboost: '20~50', cnn: '25~45', transformer: '25~45', markov: '30~50' },
            { name: '소수', range: '0~3', lstm: '2~3', xgboost: '1~3', cnn: '2~3', transformer: '2~3', markov: '2~3' },
            { name: '합성수', range: '0~6', lstm: '2~4', xgboost: '2~4', cnn: '2~4', transformer: '2~4', markov: '2~4' },
            { name: '연속', range: '0~5', lstm: '0~2', xgboost: '0~1', cnn: '0~2', transformer: '0~2', markov: '0~2' },
            { name: '제곱수', range: '0~6', lstm: '0~1', xgboost: '0~1', cnn: '0~1', transformer: '0~1', markov: '0~1' },
            { name: '삼각수', range: '0~6', lstm: '0~2', xgboost: '0~2', cnn: '0~2', transformer: '0~2', markov: '0~2' },
            { name: '동형수', range: '0~2', lstm: '0~1', xgboost: '0~1', cnn: '0~1', transformer: '0~1', markov: '0~1' },
            { name: '3배수', range: '0~6', lstm: '2~4', xgboost: '2~4', cnn: '2~4', transformer: '2~4', markov: '2~4' },
            { name: '4배수', range: '0~6', lstm: '1~3', xgboost: '1~3', cnn: '1~3', transformer: '1~3', markov: '1~3' },
            { name: '5배수', range: '0~6', lstm: '0~2', xgboost: '0~2', cnn: '0~2', transformer: '0~2', markov: '0~2' },
            { name: '배수외', range: '0~6', lstm: '2~4', xgboost: '2~4', cnn: '2~4', transformer: '2~4', markov: '2~4' }
        ];

        function renderFilters\(\) {
            const html = filters.map\(f => `
                <div class="filter-box">
                    <div class="filter-title">${f.name} - 범위: ${f.range}</div>
                    <div class="models">
                        <div class="model lstm">LSTM<br>${f.lstm}</div>
                        <div class="model xgboost">XGB<br>${f.xgboost}</div>
                        <div class="model cnn">CNN<br>${f.cnn}</div>
                        <div class="model transformer">TRF<br>${f.transformer}</div>
                        <div class="model markov">Markov<br>${f.markov}</div>
                    </div>
                </div>
            `\).join\(''\);

            document.getElementById\('filters-list'\).innerHTML = html;
        }

        function switchTab\(tab\) {
            document.querySelectorAll\('.tab-content'\).forEach\(el => el.classList.remove\('active'\)\);
            document.querySelectorAll\('.tab-btn'\).forEach\(el => el.classList.remove\('active'\)\);
            document.getElementById\(tab\).classList.add\('active'\);
            event.target.classList.add\('active'\);
        }

        renderFilters\(\);
    </script>
</body>
</html>
EOF)

Bash(powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
try {
    $r = Invoke-WebRequest -Uri ''http://localhost:8000/api/deep-analysis/v3/analysis'' -TimeoutSec 120
    $json = $r.Content | ConvertFrom-Json
    Write-Host ''success:'' $json.success
    Write-Host ''keys:'' \($json.PSObject.Properties.Name -join '', ''\)
    Write-Host ''elapsed:'' $json.elapsed_seconds
    if \($json.range_analysis\) {
        Write-Host ''range_analysis keys:'' \($json.range_analysis.PSObject.Properties.Name -join '', ''\)
    }
    if \($json.matrix_data\) {
        Write-Host ''matrix_data count:'' $json.matrix_data.Count
        Write-Host ''first item keys:'' \($json.matrix_data[0].PSObject.Properties.Name -join '', ''\)
    }
} catch {
    Write-Host ''ERROR:'' $_.Exception.GetType\(\).FullName
    Write-Host ''MESSAGE:'' $_.Exception.Message
}
")
